{"source": "def investigate(context, acquire):
    hist = acquire("history")
    # Family: put in {ignore, replace, upsert}; trigger in {none, after_insert_log};
    # channel in {changes, total_changes, total_changes_both}.
    # We simulate all 18 members and keep those consistent with every receipt.

    def simulate(put_mode, trig, chan, actions):
        # returns (channel_value, committed_count, committed_sum)
        # state: dict key->value for committed; pending per connection
        committed = {}
        # per-connection transaction state: None or dict of pending ops
        # We model: each connection has its own view; writes go to pending if in txn.
        # Simpler: track committed dict, and per-connection pending dict.
        # For non-txn writes, apply directly to committed.
        # For txn writes, apply to pending[conn].
        # commit: apply pending to committed. rollback: discard.
        # channel counts: changes() = last direct row-change count on main.
        # total_changes = cumulative direct row changes on main.
        # total_changes_both = cumulative on main + other.
        # Trigger: AFTER INSERT inserts one row into log -> adds 1 to changes()/total_changes
        # for that statement (on the connection that did the insert).
        # For INSERT OR IGNORE that ignores, no insert happens, no trigger.
        # For INSERT OR REPLACE, delete+insert: changes() counts 1 (the insert), trigger fires.
        # Actually REPLACE: if conflict, deletes old row then inserts. changes() = 1.
        # For upsert DO UPDATE: if conflict, update -> changes() = 1, no trigger (trigger is AFTER INSERT).
        # If no conflict, insert -> changes() = 1, trigger fires.
        # For IGNORE: if conflict, no change -> changes() = 0, no trigger.
        # If no conflict, insert -> changes() = 1, trigger fires.

        main_total = 0
        other_total = 0
        last_changes = 0
        pending = {"main": None, "other": None}

        def apply_write(conn, key, value, op):
            nonlocal main_total, other_total, last_changes
            # determine if row exists in the connection's view
            # For simplicity, use committed + pending for that conn
            view = dict(committed)
            if pending[conn] is not None:
                view.update(pending[conn])
            exists = key in view
            delta = 0
            trig_delta = 0
            if op == "put":
                if put_mode == "ignore":
                    if exists:
                        delta = 0
                    else:
                        delta = 1
                        trig_delta = 1 if trig else 0
                elif put_mode == "replace":
                    delta = 1
                    trig_delta = 1 if trig else 0
                else:  # upsert
                    if exists:
                        delta = 1
                        trig_delta = 0  # DO UPDATE, no insert trigger
                    else:
                        delta = 1
                        trig_delta = 1 if trig else 0
            elif op == "update":
                if exists:
                    delta = 1
                else:
                    delta = 0
            elif op == "delete":
                if exists:
                    delta = 1
                else:
                    delta = 0
            total_delta = delta + trig_delta
            if conn == "main":
                main_total += total_delta
                last_changes = total_delta
            else:
                other_total += total_delta
            # apply to pending or committed
            if pending[conn] is not None:
                if op == "put":
                    pending[conn][key] = value
                elif op == "update":
                    if exists:
                        pending[conn][key] = value
                elif op == "delete":
                    if exists:
                        del pending[conn][key]
            else:
                if op == "put":
                    committed[key] = value
                elif op == "update":
                    if exists:
                        committed[key] = value
                elif op == "delete":
                    if exists:
                        del committed[key]

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                pending[conn] = {}
            elif op == "commit":
                if pending[conn] is not None:
                    committed.update(pending[conn])
                    pending[conn] = None
            elif op == "rollback":
                pending[conn] = None
            elif op in ("put", "update", "delete"):
                key = act.get("key")
                value = act.get("value", 0)
                apply_write(conn, key, value, op)

        if chan == "changes":
            ch = last_changes
        elif chan == "total_changes":
            ch = main_total
        else:
            ch = main_total + other_total
        return ch, len(committed), sum(committed.values())

    put_modes = ["ignore", "replace", "upsert"]
    trigs = [False, True]
    chans = ["changes", "total_changes", "total_changes_both"]

    candidates = []
    for pm in put_modes:
        for tg in trigs:
            for ch in chans:
                ok = True
                for rec in hist:
                    acts = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    c, cc, cs = simulate(pm, tg, ch, acts)
                    if c != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((pm, tg, ch))

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for pm, tg, ch in candidates:
        c, cc, cs = simulate(pm, tg, ch, actions)
        if goal == "channel":
            vals.add(c)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
    if len(vals) == 1:
        return {"value": list(vals)[0], "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Simulates all 18 family members (put mode x trigger x channel) and keeps those consistent with calibration receipts; resolves a goal only when all consistent members agree.", "lesson": "The channel is changes() (last direct row-change count), not cumulative total_changes, and the put mode is INSERT OR REPLACE with no trigger: repeated puts on the same key each count 1, and rollback discards pending writes while the counter still reflects the rolled-back statement."}
